(()=>{const q=s=>document.querySelector(s),form=q('#catering-form'),money=n=>'KES '+n.toLocaleString('en-KE');const today=new Date();q('#event-date').min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
function estimate(){const n=Number(q('#event-guests').value),rate=Number(q('#event-package').value);q('#event-estimate').textContent=!q('#event-guests').checkValidity()?'Enter 10–999 guests':rate?money(n*rate):'Request a personalised quote';q('#event-wa').hidden=true}
q('#event-package').addEventListener('change',estimate);q('#event-guests').addEventListener('input',estimate);form.addEventListener('input',()=>q('#event-wa').hidden=true);form.addEventListener('change',()=>q('#event-wa').hidden=true);
document.querySelectorAll('[data-occasion]').forEach(b=>b.addEventListener('click',()=>{q('#event-type').value=b.dataset.occasion;q('#catering-planner').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});q('#event-type').focus({preventScroll:true})}));
form.addEventListener('submit',e=>{e.preventDefault();for(const id of ['event-name','event-location']){const input=q('#'+id);if(!input.value.trim()){input.setCustomValidity('Please enter this detail.');input.reportValidity();return}}if(!form.reportValidity())return;const person=q('#event-recipient').value==='joyce'?{name:'Joyce',phone:'254722165863'}:{name:'Isaac',phone:'254722693407'};const rate=Number(q('#event-package').value),guests=Number(q('#event-guests').value);const message=`Hello ${person.name}, I would like a catering quotation from Joy Ripples Resort.\n\nName: ${q('#event-name').value.trim()}\nOccasion: ${q('#event-type').value}\nDate: ${q('#event-date').value}\nServing time: ${q('#event-time').value}\nGuests: ${guests}\nLocation: ${q('#event-location').value.trim()}\nMenu direction: ${q('#event-package').selectedOptions[0].textContent}\nService preference: ${q('#event-style').value}\nIndicative food subtotal: ${rate?money(rate*guests):'Please quote'}\nPreferences / dietary needs: ${q('#event-needs').value.trim()||'To discuss'}\n\nThese are website planning estimates and service requests, not confirmed resort rates or inclusions. Please confirm availability, menu, staffing, equipment, transport, taxes, payment and cancellation terms in the final quotation.`;const a=q('#event-wa');a.href='https://wa.me/'+person.phone+'?text='+encodeURIComponent(message);a.hidden=false;window.open(a.href,'_blank','noopener,noreferrer')});['event-name','event-location'].forEach(id=>q('#'+id).addEventListener('input',()=>q('#'+id).setCustomValidity('')));estimate();})();
